import os

def delete_files(folder):
    for root, dirs, files in os.walk(folder):
        for file in files:
            if file.endswith('.log'):
                os.chmod(os.path.join(root, file), 0o777)
                os.remove(os.path.join(root, file))

delete_files('/var/log')

